import React from 'react';
import { useAuth } from '../context/AuthContext';
import { Download, Eye } from 'lucide-react';
import roadmapImage from '../assets/roadmapp.png';

const WeeklyFocus = () => {
    const { user } = useAuth();

    return (
        <div className="max-w-7xl mx-auto px-4">
            {/* Header */}
            <div className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 rounded-2xl p-6 mb-6 text-white">
                <div className="flex items-center justify-between flex-wrap gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold">
                            🚀 Full Stack + AI Roadmap
                        </h1>
                        <p className="text-blue-100">Your 4-month journey to become a software engineer</p>
                    </div>
                    <div className="flex gap-3">
                        <button 
                            onClick={() => window.open('/roadmapp.png', '_blank')}
                            className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                        >
                            <Eye size={18} />
                            View Full
                        </button>
                        <button 
                            onClick={() => {
                                const link = document.createElement('a');
                                link.href = roadmapImage;
                                link.download = 'Roadmap.png';
                                link.click();
                            }}
                            className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm font-medium transition flex items-center gap-2"
                        >
                            <Download size={18} />
                            Download
                        </button>
                    </div>
                </div>
            </div>

            {/* Roadmap Image */}
            <div className="bg-white rounded-xl shadow-lg border border-gray-200 p-4 overflow-hidden">
                <img 
                    src={roadmapImage} 
                    alt="Java Full Stack + AI Engineer Roadmap"
                    className="w-full h-auto rounded-lg"
                    style={{ maxHeight: '80vh', objectFit: 'contain' }}
                />
            </div>

            {/* Footer */}
            <div className="mt-6 text-center text-sm text-gray-400">
                Made by Swaliha • Keep Learning, Keep Growing! 🚀
            </div>
        </div>
    );
};

export default WeeklyFocus;
